INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (599, 1, '가상화를 쓰는 이유', '물리 서버 한 대 위에 여러 가상 머신을 올려 운영하는 가장 큰 이유로 알맞은 것은?', '자원 활용률과 격리·유연성 측면을 생각해 보세요.', NULL, NULL, '[]', 'choice', '["서버를 통합해 자원을 효율적으로 쓰고 격리된 환경을 쉽게 만든다", "가상 머신은 항상 물리 서버보다 빠르기 때문이다", "가상 머신에는 운영체제가 필요 없기 때문이다", "가상화를 하면 하드웨어가 고장나지 않기 때문이다"]', 0, '가상화는 한 서버의 자원을 여러 VM 이 나눠 써 활용률을 높이고, VM 단위로 격리·복제·이동이 쉬워 운영이 유연해집니다. 보통 약간의 성능 손실이 있고 VM 마다 운영체제가 필요합니다.', NULL, NULL, NULL, NULL),
  (599, 2, '하이퍼바이저의 두 종류', '하드웨어 위에서 직접 동작하는 하이퍼바이저(Type 1)와 일반 운영체제 위에서 하나의 응용처럼 동작하는 하이퍼바이저(Type 2)의 예로 알맞은 것은?', '호스트 OS 가 있는지 없는지로 나눕니다.', NULL, NULL, '[]', 'choice', '["Type 1 은 VirtualBox, Type 2 는 VMware ESXi", "Type 1 은 Docker, Type 2 는 Kubernetes", "두 종류 모두 일반 운영체제가 필요 없다", "Type 1 은 VMware ESXi, Type 2 는 VirtualBox"]', 3, 'Type 1(베어메탈)은 하드웨어 위에 직접 올라가고 ESXi·Xen 이 대표적이며, Type 2(호스티드)는 호스트 OS 위에서 동작하고 VirtualBox·VMware Workstation 이 대표적입니다. KVM 은 리눅스 커널 모듈이라 경계에 있다는 해석이 있습니다.', NULL, NULL, NULL, NULL),
  (599, 3, '하드웨어 보조 가상화', 'Intel VT-x 나 AMD-V 같은 CPU 의 가상화 지원 기능이 해 주는 일로 가장 알맞은 것은?', '게스트가 실행되는 CPU 모드를 하드웨어가 지원합니다.', NULL, NULL, '[]', 'choice', '["디스크의 읽기·쓰기 속도를 두 배로 올려 준다", "모든 네트워크 패킷을 자동으로 암호화해 준다", "게스트 코드를 하드웨어가 직접 실행해 개입을 줄인다", "VM 마다 별도의 물리 CPU 를 영구히 할당해 준다"]', 2, 'VT-x·AMD-V 는 게스트용 CPU 실행 모드를 제공해 특권 명령을 하이퍼바이저가 일일이 가로채지 않아도 되게 합니다. 이전의 소프트웨어 방식(바이너리 변환, 반가상화)보다 성능이 높고 구현이 단순합니다.', NULL, NULL, NULL, NULL),
  (599, 4, 'KVM 과 QEMU', '리눅스 KVM 환경에서 KVM 과 QEMU 의 역할 구분으로 가장 알맞은 것은?', '커널 모듈과 사용자 공간 프로세스의 역할이 다릅니다.', NULL, NULL, '[]', 'choice', '["KVM 은 장치를 에뮬레이션하고 QEMU 는 CPU 를 가상화한다", "KVM 은 커널에서 CPU·메모리를, QEMU 는 장치와 VM 프로세스를 맡는다", "KVM 과 QEMU 는 같은 프로그램의 다른 이름이다", "KVM 은 VM 의 디스크 이미지 파일 형식이다"]', 1, 'KVM 은 리눅스를 하이퍼바이저로 바꾸는 커널 모듈로 하드웨어 보조 기능을 써서 CPU·메모리를 가상화하고, QEMU 는 VM 마다 사용자 공간 프로세스로 실행되며 디스크·NIC 등 장치를 에뮬레이션합니다.', NULL, NULL, NULL, NULL),
  (599, 5, 'libvirt 의 역할', 'libvirt 와 virsh 의 역할로 가장 알맞은 것은?', 'VM 을 만드는 엔진이 아니라 관리하는 계층입니다.', NULL, NULL, '[]', 'choice', '["여러 하이퍼바이저를 공통 인터페이스로 관리하는 API 와 도구", "VM 의 CPU 를 직접 가상화하는 커널 모듈", "VM 안의 애플리케이션을 설치하는 패키지 관리자", "VM 디스크 이미지를 압축하는 프로그램"]', 0, 'libvirt 는 KVM·QEMU·Xen 등을 같은 API 로 관리(정의·시작·정지·네트워크·스토리지)하는 계층이고 virsh 는 그 명령행 도구입니다. 실제 VM 실행은 QEMU/KVM 이 맡습니다.', NULL, NULL, NULL, NULL),
  (599, 6, 'EPT 와 2단계 주소 변환', 'VM 의 메모리 접근이 느려지지 않도록 CPU 가 게스트 주소를 호스트 물리 주소로 변환하는 일을 하드웨어로 돕는 기능(Intel EPT, AMD NPT)이 해결하는 문제는?', '게스트 가상 → 게스트 물리 → 호스트 물리, 두 번 변환해야 합니다.', NULL, NULL, '[]', 'choice', '["디스크 입출력을 호스트 메모리에 캐시해 준다", "VM 끼리의 네트워크 통신을 자동으로 암호화한다", "VM 의 CPU 클럭 속도를 물리 한계 이상으로 높인다", "게스트 → 호스트 주소 변환의 소프트웨어 비용을 줄인다"]', 3, '가상화 환경에서는 게스트 가상주소가 게스트 물리주소를 거쳐 호스트 물리주소로 두 번 변환됩니다. EPT/NPT 는 이 2단계 변환을 하드웨어가 처리해 소프트웨어(섀도 페이지 테이블) 방식의 큰 오버헤드를 없앱니다.', NULL, NULL, NULL, NULL),
  (599, 7, 'virtio 의 의미', 'VM 에 가상 디스크·NIC 를 붙일 때 에뮬레이션 장치(e1000) 대신 virtio 를 권하는 이유로 알맞은 것은?', '게스트가 가상 장치임을 알고 효율적으로 통신합니다.', NULL, NULL, '[]', 'choice', '["실제 하드웨어보다 항상 느리지만 호환성이 높다", "게스트에 별도 드라이버가 전혀 필요 없다", "가상 환경을 아는 반가상화 장치라 입출력이 효율적이다", "디스크 암호화를 자동으로 켜 주는 기능이다"]', 2, 'virtio 는 가상 장치 전용 반가상화 인터페이스로 실제 하드웨어를 흉내 내는 에뮬레이션보다 오버헤드가 적습니다. 게스트에 virtio 드라이버가 필요하고, 리눅스 게스트는 보통 기본으로 포함합니다.', NULL, NULL, NULL, NULL),
  (599, 8, 'vCPU 의 실체', 'VM 의 vCPU 하나는 KVM 환경에서 호스트에서 어떤 형태로 존재할까요?', '호스트 스케줄러가 다루는 단위입니다.', NULL, NULL, '[]', 'choice', '["물리 코어 하나를 영구히 점유하는 고정 자원이다", "호스트의 스레드이며 스케줄러가 물리 CPU 에 배정한다", "디스크에 저장된 설정 값일 뿐 실행되지 않는다", "VM 안에서 동작하는 프로세스 하나일 뿐이다"]', 1, 'QEMU/KVM 에서 vCPU 는 호스트의 스레드이고 호스트 스케줄러가 물리 코어에 번갈아 올립니다. 그래서 vCPU 합계를 물리 코어보다 많게 잡는 오버커밋이 가능하고, 지나치면 대기(steal)가 늘어납니다.', NULL, NULL, NULL, NULL),
  (599, 9, 'VM 과 컨테이너', 'VM 과 컨테이너의 가장 근본적인 차이로 알맞은 것은?', '커널을 공유하는지 아닌지를 생각해 보세요.', NULL, NULL, '[]', 'choice', '["VM 은 게스트마다 별도 커널이 있고, 컨테이너는 호스트 커널을 공유한다", "VM 은 커널 없이 동작하고 컨테이너는 자체 커널을 가진다", "둘 다 호스트 커널을 공유하며 격리 강도가 같다", "컨테이너는 하드웨어 보조 기능이 필요하고 VM 은 필요 없다"]', 0, 'VM 은 가상 하드웨어 위에서 자체 커널을 돌려 격리가 강하고 무겁고, 컨테이너는 호스트 커널을 공유해 가볍고 빠르지만 커널 취약점의 영향을 공유합니다. 용도에 따라 함께 쓰기도 합니다.', NULL, NULL, NULL, NULL),
  (599, 10, '가상화 지원 CPU 플래그', 'CPU 가 **하드웨어 가상화(Intel VT-x 또는 AMD-V)** 를 지원하는지 `/proc/cpuinfo` 에서 확인합니다. 빈칸에 들어갈 플래그 패턴을 채우세요. (개수가 0 이면 지원하지 않거나 BIOS 에서 꺼진 것)', 'Intel 과 AMD 의 플래그 이름이 서로 다릅니다. 둘 다 잡는 패턴을 고르세요.', NULL, NULL, '[]', 'fill', '["vmx|svm", "kvm|qemu", "sse|avx", "lm|nx"]', NULL, '`vmx`(Intel VT-x)와 `svm`(AMD-V) 플래그가 보이면 하드웨어 가상화를 지원합니다. `kvm|qemu` 는 CPU 플래그가 아니고, `sse|avx` 는 벡터 연산, `lm|nx` 는 64비트와 실행 방지 기능입니다.', '[0]', 'grep -c -E ''({0})'' /proc/cpuinfo', NULL, NULL),
  (599, 11, 'KVM 사용 가능 여부', 'KVM 이 사용 가능하면 호스트에 존재하는 **장치 파일** 이름을 채우세요.', '가상화 모듈 이름과 같은 파일입니다.', NULL, NULL, '[]', 'fill', '["kvm", "qemu", "vmx", "virt"]', NULL, '`/dev/kvm` 이 있어야 QEMU 가 하드웨어 가속(KVM)을 쓸 수 있습니다. 없으면 모듈이 올라오지 않았거나 BIOS 에서 가상화가 꺼져 있을 수 있습니다.', '[0]', 'ls -l /dev/{0}', NULL, NULL),
  (599, 12, 'VM 안의 애플리케이션이 실행되는 계층', 'KVM 환경에서 VM 안의 애플리케이션이 실행되기까지 아래에서 위로 쌓이는 계층입니다. 올바른 순서로 놓으세요.', '물리 장치부터 위로 올라갑니다.', NULL, NULL, '[]', 'order', '["VM 안에서 동작하는 애플리케이션", "게스트 운영체제", "호스트 리눅스 커널과 KVM 모듈 위의 QEMU 프로세스", "물리 서버 하드웨어(CPU·메모리)"]', NULL, '물리 하드웨어 위에 호스트 커널(KVM)이 있고, 그 위에서 QEMU 프로세스가 VM 을 실행하며, 그 안에 게스트 운영체제와 애플리케이션이 올라갑니다.', '[3, 2, 1, 0]', NULL, NULL, NULL);
